alter table public.roles enable row level security;alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.product_variants enable row level security;alter table public.product_images enable row level security;alter table public.inventory_movements enable row level security;alter table public.customers enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.financial_transactions enable row level security;alter table public.ai_generations enable row level security;alter table public.notifications enable row level security;alter table public.audit_logs enable row level security;
create policy roles_read on public.roles for select using(auth.uid() is not null);create policy profiles_read on public.profiles for select using(id=auth.uid() or public.current_role()='ADMIN');create policy profiles_admin_update on public.profiles for update using(public.current_role()='ADMIN') with check(public.current_role()='ADMIN');create policy categories_read on public.categories for select using(auth.uid() is not null);create policy categories_write on public.categories for all using(public.current_role() in('ADMIN','CONTENT_MANAGER')) with check(public.current_role() in('ADMIN','CONTENT_MANAGER'));create policy products_read on public.products for select using(auth.uid() is not null);create policy products_write on public.products for all using(public.current_role() in('ADMIN','CONTENT_MANAGER')) with check(public.current_role() in('ADMIN','CONTENT_MANAGER'));create policy variants_read on public.product_variants for select using(auth.uid() is not null);create policy variants_insert on public.product_variants for insert with check(public.current_role() in('ADMIN','CONTENT_MANAGER','WAREHOUSE_MANAGER'));create policy variants_update on public.product_variants for update using(public.current_role() in('ADMIN','CONTENT_MANAGER','WAREHOUSE_MANAGER')) with check(public.current_role() in('ADMIN','CONTENT_MANAGER','WAREHOUSE_MANAGER'));create policy images_read on public.product_images for select using(auth.uid() is not null);create policy images_write on public.product_images for all using(public.current_role() in('ADMIN','CONTENT_MANAGER')) with check(public.current_role() in('ADMIN','CONTENT_MANAGER'));create policy movements_read on public.inventory_movements for select using(auth.uid() is not null);create policy customer_ops on public.customers for all using(public.current_role() in('ADMIN','WAREHOUSE_MANAGER')) with check(public.current_role() in('ADMIN','WAREHOUSE_MANAGER'));create policy order_ops on public.orders for all using(public.current_role() in('ADMIN','WAREHOUSE_MANAGER')) with check(public.current_role() in('ADMIN','WAREHOUSE_MANAGER'));create policy order_item_ops on public.order_items for all using(public.current_role() in('ADMIN','WAREHOUSE_MANAGER')) with check(public.current_role() in('ADMIN','WAREHOUSE_MANAGER'));create policy finance_admin on public.financial_transactions for all using(public.current_role()='ADMIN') with check(public.current_role()='ADMIN');create policy ai_ops on public.ai_generations for all using(public.current_role() in('ADMIN','CONTENT_MANAGER')) with check(public.current_role() in('ADMIN','CONTENT_MANAGER'));create policy notifications_read on public.notifications for select using(user_id=auth.uid() or user_id is null);create policy notifications_update on public.notifications for update using(user_id=auth.uid()) with check(user_id=auth.uid());create policy audit_admin on public.audit_logs for select using(public.current_role()='ADMIN');